// Verus solution for the turn-based battle problem.
//
// Key idea:
// turns_to_defeat(H, S) = ceil(H / S) = (H + S - 1) / S (integer division).
// Takahashi wins iff turns_to_defeat(C, B) <= turns_to_defeat(A, D).

#![allow(unused_imports)]
